body:
`EncryptionKeyCapability` sets `PORTAL_ENCRYPTION_NOC_ROLE_ARN` to an empty string for feature stacks (`stack_id` set). This module unconditionally constructs `AWSCloudCredentials`/`CloudKeyManager` at import time using `encryption_settings.noc_role_arn`; if that value is empty, the NBN keyserver auth/client may raise during import and prevent the app/Lambda from starting (notably `portal-eventhub` imports `portal.data.messages.instances` just to access `nbn_api_client`). Consider lazily constructing the CloudKeyManager and/or disabling outbound encryption when `noc_role_arn` is empty, so consumers that don’t need outbound encryption can still start reliably.
```suggestion
def _build_cloud_key_manager() -> CloudKeyManager:
    if not encryption_settings.noc_role_arn:
        raise RuntimeError(
            "Outbound encryption is not configured because "
            "encryption_settings.noc_role_arn is empty."
        )

    cloud_credentials = AWSCloudCredentials(noc_role_arn=encryption_settings.noc_role_arn)

    return CloudKeyManager(
        credentials=cloud_credentials,  # type: ignore[arg-type]  # AWSCloudCredentials implements CloudCredentials protocol
        environment=encryption_settings.noc_environment,
        group=encryption_settings.group,
        address=encryption_settings.address,
    )


class _LazyCloudKeyManager:
    def __init__(self) -> None:
        self._key_manager: CloudKeyManager | None = None

    def _get_key_manager(self) -> CloudKeyManager:
        if self._key_manager is None:
            self._key_manager = _build_cloud_key_manager()
        return self._key_manager

    def __getattr__(self, item: str):
        return getattr(self._get_key_manager(), item)


outbound_encryption_service: OutboundEncryptionService = OutboundEncryptionService(
    key_manager=_LazyCloudKeyManager(),
